import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import '../../learning/models/question_attempt.dart';

/// Data-layer contract for the attempts subcollection.
///
/// Manages `users/{uid}/attempts/{attemptId}` documents in Firestore.
/// This is the **core source of truth** for the learning engine.
/// The repository is the *only* place in the app that reads or writes
/// attempts — no UI or provider touches Firestore directly.
///
/// ## Firestore path
/// `users/{uid}/attempts/{attemptId}`
///
/// ## Document ID
/// Auto-generated by Firestore. The generated ID is stored back in the
/// `attemptId` field for convenience.
///
/// ## Document lifecycle
/// Documents are **append-only** — created by [record], never updated or deleted.
/// This matches the security rules in `docs/firestore_schema.md`.
///
/// ## Fields written
/// | Field            | Type        |
/// |------------------|-------------|
/// | `attemptId`      | `String`    |
/// | `questionId`     | `String`    |
/// | `subjectId`      | `String`    |
/// | `chapterId`      | `String`    |
/// | `selectedOption` | `int`       |
/// | `correctOption`  | `int`       |
/// | `isCorrect`      | `bool`      |
/// | `attemptedAt`    | `Timestamp` |
/// | `timeTakenMs`    | `int`       |
/// | `attemptNumber`  | `int`       |
///
/// See `docs/firestore_schema.md` for the full field reference.
class LearningRepository {
  LearningRepository({
    FirebaseFirestore? firestore,
    FirebaseAuth? auth,
  })  : _firestore = firestore ?? FirebaseFirestore.instance,
        _auth = auth ?? FirebaseAuth.instance;

  final FirebaseFirestore _firestore;
  final FirebaseAuth _auth;

  // ── Helpers ────────────────────────────────────────────────────────────────

  /// Returns the `users/{uid}/attempts` [CollectionReference].
  /// Throws a [StateError] if no user is authenticated.
  CollectionReference<Map<String, dynamic>> get _attemptsCol {
    final uid = _auth.currentUser?.uid;
    if (uid == null) {
      throw StateError('LearningRepository: no authenticated user.');
    }
    return _firestore.collection('users').doc(uid).collection('attempts');
  }

  // ── Record ─────────────────────────────────────────────────────────────────

  /// Persists a single [QuestionAttempt] as a new Firestore document.
