  /// This is the primary feed for [learningProvider] — the same data that
  /// currently lives in the in-memory `List<QuestionAttempt>`.
  ///
  /// This method does **not** read from Firestore yet.
  /// Wire it to `FirebaseFirestore` in Sprint 10.5.
  Stream<List<QuestionAttempt>> watchAll() {
    // Sprint 10.5: replace with actual Firestore stream.
    // return _attemptsCol
    //     .orderBy('attemptedAt')
    //     .snapshots()
    //     .map((snap) => snap.docs.map(_fromDoc).toList());
    return const Stream.empty();
  }

  // ── Watch for chapter ──────────────────────────────────────────────────────

  /// Returns a live stream of all attempts for a specific [chapterId].
  ///
  /// Used by chapter-progress providers.
  ///
  /// Requires a composite index on `chapterId ASC, attemptedAt ASC`.
  /// See `docs/firestore_schema.md → Query Indexes Required`.
  ///
  /// This method does **not** read from Firestore yet.
  /// Wire it to `FirebaseFirestore` in Sprint 10.5.
  Stream<List<QuestionAttempt>> watchForChapter(String chapterId) {
    // Sprint 10.5: replace with actual Firestore stream.
