    return const Stream.empty();
  }

  // ── Watch for subject ──────────────────────────────────────────────────────

  /// Returns a live stream of all attempts for a specific [subjectId].
  ///
  /// Used by subject-progress providers.
  ///
  /// Requires a composite index on `subjectId ASC, attemptedAt ASC`.
  /// See `docs/firestore_schema.md → Query Indexes Required`.
  ///
  /// This method does **not** read from Firestore yet.
  /// Wire it to `FirebaseFirestore` in Sprint 10.5.
  Stream<List<QuestionAttempt>> watchForSubject(String subjectId) {
